# /etc/radvd.conf
interface eth0
{
  AdvSendAdvert on;
  AdvManagedFlag off;          # M=0
  AdvOtherConfigFlag on;       # O=1 → DHCPv6 无状态取 DNS
  prefix 2001:db8:10::/64
  {
    AdvOnLink on;              # L=1
    AdvAutonomous on;          # A=1
    AdvValidLifetime 86400;    # valid 1 天
    AdvPreferredLifetime 14400;# preferred 4 小时
  };
  RDNSS 240c::6666 { };
};
